	echo Built with Makeself version 2.5.0
	echo Build command was: "/usr/local/share/makeself/makeself.sh \\
    \"-q\" \\
    \"--keep-umask\" \\
    \"/tmp/tmp.K36qI2urLBtlmksel\" \\
    \"update-tlmgr-r79653.sh\" \\
    \"TeX Live Manager Updater\" \\
    \"./runme.sh\""
